const oldestUnpublishedOutbox = `-- name: OldestUnpublishedOutbox :one
SELECT COALESCE(min(available_at), $1)::timestamptz AS oldest FROM outbox_events
WHERE published_at IS NULL AND available_at <= $1
`

func (q *Queries) OldestUnpublishedOutbox(ctx context.Context, now time.Time) (time.Time, error) {
	row := q.db.QueryRow(ctx, oldestUnpublishedOutbox, now)
	var oldest time.Time
	err := row.Scan(&oldest)
	return oldest, err
}

